{"code": "from typing import Any

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel

PAGE_SIZE = 2

_ITEMS = {
    1: {"id": 1, "name": "bolt", "qty": 40},
    2: {"id": 2, "name": "nut", "qty": 12},
    3: {"id": 3, "name": "washer", "qty": 7},
}

app = FastAPI()


class Item(BaseModel):
    id: int
    name: str
    qty: Any


class ItemList(BaseModel):
    items: list[Item]
    count: int


class CreateItemResponse(BaseModel):
    id: int
    name: str
    qty: Any


class HealthResponse(BaseModel):
    status: str
    page_size: int


@app.get("/items", response_model=ItemList)
def list_items(request: Request):
    limit_param = request.query_params.get("limit")
    if limit_param is None:
        limit = PAGE_SIZE
    else:
        try:
            parsed = int(limit_param)
        except ValueError:
            parsed = 0
        limit = parsed or PAGE_SIZE

    items = list(_ITEMS.values())[:limit]
    return {"items": items, "count": len(items)}


@app.get("/items/{item_id}", response_model=Item)
def get_item(item_id: int):
    item = _ITEMS.get(item_id)
    if item is None:
        return JSONResponse(status_code=404, content={"error": "item not found"})
    return item


@app.post("/items", response_model=CreateItemResponse, status_code=201)
async def create_item(request: Request):
    try:
        data = await request.json()
    except Exception:
        return JSONResponse(status_code=400, content={"error": "body must be JSON"})

    if not data:
        return JSONResponse(status_code=400, content={"error": "body must be JSON"})
    if "name" not in data:
        return JSONResponse(status_code=400, content={"error": "name is required"})
    if not isinstance(data["name"], str):
        return JSONResponse(status_code=400, content={"error": "name must be a string"})

    qty = data.get("qty", 0)
    new_id = max(_ITEMS) + 1
    return {"id": new_id, "name": data["name"], "qty": qty}


@app.delete("/items/{item_id}")
def delete_item(item_id: int):
    if item_id not in _ITEMS:
        return JSONResponse(status_code=404, content={"error": "item not found"})
    return {"deleted": item_id}


@app.get("/health", response_model=HealthResponse)
def health():
    return {"status": "ok", "page_size": PAGE_SIZE}
"}

{"code":""""Token-guarded FastAPI migration."""

from typing import Any, Optional

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Request, status
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI()

_TOKENS = {"secret-token": {"user": "ana", "role": "admin"}}
_NOTES = {1: {"id": 1, "owner": "ana", "text": "first"}}


class Identity(BaseModel):
    user: str
    role: str


class NoteCreate(BaseModel):
    model_config = ConfigDict(extra="ignore")

    text: Any = None


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException) -> JSONResponse:
    return JSONResponse(
        status_code=exc.status_code,
        content=exc.detail,
        headers=exc.headers,
    )


@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError) -> JSONResponse:
    return JSONResponse(
        status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
        content={"error": "text is required", "code": "VAL_001"},
    )


api = APIRouter(prefix="/api/v1")


async def get_identity(
    x_api_token: Optional[str] = Header(default=None, alias="X-Api-Token"),
) -> Identity:
    if not x_api_token:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": "missing token", "code": "AUTH_001"},
        )
    identity = _TOKENS.get(x_api_token)
    if identity is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": "invalid token", "code": "AUTH_002"},
        )
    return Identity(**identity)


@api.get("/whoami")
def whoami(identity: Identity = Depends(get_identity)):
    return {"user": identity.user, "role": identity.role}


@api.get("/notes/{note_id}")
def get_note(note_id: str, identity: Identity = Depends(get_identity)):
    try:
        note_id_int = int(note_id)
    except ValueError:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={"error": "not found"},
        )
    note = _NOTES.get(note_id_int)
    if note is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={"error": "not found"},
        )
    if note["owner"] != identity.user:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail={"error": "forbidden"},
        )
    return note


@api.post("/notes", status_code=status.HTTP_201_CREATED)
def create_note(payload: NoteCreate, identity: Identity = Depends(get_identity)):
    if not payload.text:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail={"error": "text is required", "code": "VAL_001"},
        )
    return {"id": 2, "owner": identity.user, "text": payload.text}


app.include_router(api)
"}

{"code": "from http import HTTPStatus

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI()

_ACCOUNTS = {"a1": {"id": "a1", "balance": 100}}


class InsufficientFunds(Exception):
    def __init__(self, needed, available):
        super().__init__("insufficient funds")
        self.needed = needed
        self.available = available


class WithdrawRequest(BaseModel):
    amount: int = Field(gt=0)


@app.exception_handler(InsufficientFunds)
async def on_insufficient_funds(request: Request, exc: InsufficientFunds):
    return JSONResponse(
        status_code=409,
        content={
            "error": "insufficient_funds",
            "needed": exc.needed,
            "available": exc.available,
        },
    )


@app.exception_handler(StarletteHTTPException)
async def on_http_error(request: Request, exc: StarletteHTTPException):
    return JSONResponse(
        status_code=exc.status_code,
        content={
            "error": "http_error",
            "status": exc.status_code,
            "message": HTTPStatus(exc.status_code).phrase,
        },
    )


@app.exception_handler(RequestValidationError)
async def on_request_validation_error(request: Request, exc: RequestValidationError):
    return JSONResponse(status_code=400, content={"error": "bad_amount"})


@app.get("/accounts/{account_id}")
async def get_account(account_id: str):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            status_code=404,
            content={"error": "not_found", "resource": "account"},
        )
    return account


@app.post("/accounts/{account_id}/withdraw")
async def withdraw(account_id: str, payload: WithdrawRequest):
    account = _ACCOUNTS.get(account_id)
    if account is None:
        return JSONResponse(
            status_code=404,
            content={"error": "not_found", "resource": "account"},
        )

    amount = payload.amount
    if amount > account["balance"]:
        raise InsufficientFunds(amount, account["balance"])

    return {
        "id": account_id,
        "withdrawn": amount,
        "balance": account["balance"] - amount,
    }
"}

