{"code": """"Bulk endpoint returning multi-status. Synthetic case for this benchmark.

Exercises: a JSON *array* request body (not an object), per-item outcomes, HTTP
207, and a partial-failure path that still returns 2xx.
"""

from typing import List, Optional

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()

_KNOWN = {'a', 'b', 'c'}


class BulkResult(BaseModel):
    index: int
    status: str
    reason: Optional[str] = None


class BulkResponse(BaseModel):
    results: List[BulkResult]
    failed: int


class LimitsResponse(BaseModel):
    max_items: int
    known: List[str]


@app.post('/bulk/verify')
async def bulk_verify(request: Request):
    try:
        payload = await request.json()
    except ValueError:
        return JSONResponse({'error': 'body must be JSON'}, status_code=400)

    if payload is None:
        return JSONResponse({'error': 'body must be JSON'}, status_code=400)
    if not isinstance(payload, list):
        return JSONResponse({'error': 'body must be a JSON array'}, status_code=400)
    if not payload:
        return JSONResponse({'error': 'array must not be empty'}, status_code=400)

    results: List[BulkResult] = []
    for index, key in enumerate(payload):
        if not isinstance(key, str):
            results.append(BulkResult(index=index, status='invalid', reason='not a string'))
        elif key in _KNOWN:
            results.append(BulkResult(index=index, status='ok'))
        else:
            results.append(BulkResult(index=index, status='unknown'))

    failed = sum(1 for r in results if r.status != 'ok')
    status_code = 200 if failed == 0 else 207
    response = BulkResponse(results=results, failed=failed)
    return JSONResponse(response.model_dump(exclude_none=True), status_code=status_code)


@app.get('/bulk/limits')
def limits():
    return LimitsResponse(max_items=100, known=sorted(_KNOWN))"}

{"code": "import re
from typing import List, Optional

from fastapi import Body, FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI(redirect_slashes=False)

_TASKS = {1: {"id": 1, "title": "write migration", "done": False}}


class Task(BaseModel):
    id: int
    title: str
    done: bool


class TaskListResponse(BaseModel):
    tasks: List[Task]


class DeletedResponse(BaseModel):
    deleted: int


@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError):
    return JSONResponse(status_code=400, content={"error": "title is required"})


@app.get("/tasks", response_model=TaskListResponse)
def list_tasks():
    return {"tasks": list(_TASKS.values())}


@app.post("/tasks", response_model=Task, status_code=201)
def create_task(payload: Optional[dict] = Body(default=None)):
    payload = payload or {}
    if "title" not in payload:
        return JSONResponse(status_code=400, content={"error": "title is required"})
    return {"id": 2, "title": payload["title"], "done": False}


@app.get("/tasks/{task_id}", response_model=Task)
def get_task(task_id: str):
    if not re.fullmatch(r"-?\d+", task_id):
        return JSONResponse(status_code=404, content={"error": "task not found"})
    task = _TASKS.get(int(task_id))
    if task is None:
        return JSONResponse(status_code=404, content={"error": "task not found"})
    return task


@app.put("/tasks/{task_id}", response_model=Task)
def update_task(task_id: str, payload: Optional[dict] = Body(default=None)):
    if not re.fullmatch(r"-?\d+", task_id):
        return JSONResponse(status_code=404, content={"error": "task not found"})
    task = _TASKS.get(int(task_id))
    if task is None:
        return JSONResponse(status_code=404, content={"error": "task not found"})
    payload = payload or {}
    if "title" not in payload:
        return JSONResponse(status_code=400, content={"error": "title is required"})
    return {**task, "title": payload["title"]}


@app.delete("/tasks/{task_id}", response_model=DeletedResponse)
def delete_task(task_id: str):
    if not re.fullmatch(r"-?\d+", task_id):
        return JSONResponse(status_code=404, content={"error": "task not found"})
    task_id_int = int(task_id)
    if task_id_int not in _TASKS:
        return JSONResponse(status_code=404, content={"error": "task not found"})
    return {"deleted": task_id_int}
"}

