{"code":"from typing import Any, Optional

from fastapi import FastAPI, Request, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict

app = FastAPI()

TRANSITIONS = {
    "draft": ["submitted", "cancelled"],
    "submitted": ["approved", "rejected", "cancelled"],
    "approved": ["fulfilled"],
    "rejected": [],
    "cancelled": [],
    "fulfilled": [],
}
TERMINAL = {"rejected", "cancelled", "fulfilled"}

_ORDERS = {
    "o1": {"id": "o1", "state": "draft", "total": 30, "lines": 2},
    "o2": {"id": "o2", "state": "approved", "total": 90, "lines": 5},
}
_IDEMPOTENCY = {}
_NEXT = [3]


class OrderWithTerminal(BaseModel):
    model_config = ConfigDict(extra="allow")

    id: Any
    state: Any
    total: Any
    lines: Any
    terminal: bool


def _present(order):
    return OrderWithTerminal.model_validate(
        {**order, "terminal": order["state"] in TERMINAL}
    ).model_dump()


async def _get_json_body(request: Request):
    content_type = request.headers.get("content-type", "")
    mimetype = content_type.split(";")[0].strip().lower()
    if mimetype != "application/json" and not (
        mimetype.startswith("application/") and mimetype.endswith("+json")
    ):
        return None
    try:
        return await request.json()
    except Exception:
        return None


@app.get("/orders/{order_id}")
async def get_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse({"error": "order not found", "id": order_id}, status_code=404)
    return JSONResponse(_present(order))


@app.post("/orders")
async def create_order(request: Request):
    body = await _get_json_body(request) or {}
    if not isinstance(body, dict):
        body = {}

    total = body.get("total")
    if not isinstance(total, int) or total <= 0:
        return JSONResponse({"error": "total must be a positive integer"}, status_code=400)

    key = request.headers.get("Idempotency-Key")
    if key:
        seen = _IDEMPOTENCY.get(key)
        if seen is not None:
            if seen["total"] != total:
                return JSONResponse(
                    {
                        "error": "idempotency key reused with a different body",
                        "code": "IDEMPOTENCY_MISMATCH",
                    },
                    status_code=422,
                )
            return JSONResponse(_present(_ORDERS[seen["id"]]), status_code=200)

    order_id = f"o{_NEXT[0]}"
    _NEXT[0] += 1
    order = {
        "id": order_id,
        "state": "draft",
        "total": total,
        "lines": body.get("lines", 1),
    }
    _ORDERS[order_id] = order
    if key:
        _IDEMPOTENCY[key] = {"id": order_id, "total": total}

    return JSONResponse(
        _present(order),
        status_code=201,
        headers={"Location": f"/orders/{order_id}"},
    )


@app.post("/orders/{order_id}/transition")
async def transition(order_id: str, request: Request):
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse({"error": "order not found", "id": order_id}, status_code=404)

    body = await _get_json_body(request) or {}
    if not isinstance(body, dict):
        body = {}

    target = body.get("to")
    if not target:
        return JSONResponse({"error": "to is required"}, status_code=400)
    if target not in TRANSITIONS:
        return JSONResponse({"error": "unknown state", "state": target}, status_code=400)

    allowed = TRANSITIONS[order["state"]]
    if target not in allowed:
        return JSONResponse(
            {
                "error": "illegal transition",
                "from": order["state"],
                "to": target,
                "allowed": allowed,
            },
            status_code=409,
        )

    order["state"] = target
    return JSONResponse(_present(order))


@app.delete("/orders/{order_id}")
async def delete_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return JSONResponse({"error": "order not found", "id": order_id}, status_code=404)
    if order["state"] != "draft":
        return JSONResponse(
            {
                "error": "only draft orders can be deleted",
                "state": order["state"],
                "code": "NOT_DELETABLE",
            },
            status_code=409,
        )
    return Response(status_code=204)


@app.get("/orders")
async def list_orders(state: Optional[str] = None):
    rows = list(_ORDERS.values())
    if state:
        if state not in TRANSITIONS:
            return JSONResponse({"error": "unknown state", "state": state}, status_code=400)
        rows = [o for o in rows if o["state"] == state]
    return JSONResponse({"orders": [_present(o) for o in rows], "count": len(rows)})
"}

{"code":"'''Small inventory service. Synthetic case, written for this benchmark.

Exercises: JSON body handling, manual validation with explicit 400s, a query
parameter with a default, path converters, and 404 on a missing resource.
'''

from fastapi import Depends, FastAPI, Request
from fastapi.responses import JSONResponse
import json

app = FastAPI()

PAGE_SIZE = 2

_ITEMS = {
    1: {'id': 1, 'name': 'bolt', 'qty': 40},
    2: {'id': 2, 'name': 'nut', 'qty': 12},
    3: {'id': 3, 'name': 'washer', 'qty': 7},
}


def get_page_size() -> int:
    return PAGE_SIZE


def _json_error(message: str, status_code: int) -> JSONResponse:
    return JSONResponse(content={'error': message}, status_code=status_code)


def _is_json_content_type(content_type) -> bool:
    if content_type is None:
        return False
    mimetype = content_type.split(';', 1)[0].strip().lower()
    return mimetype == 'application/json' or mimetype.endswith('+json')


@app.get('/health')
def health(page_size: int = Depends(get_page_size)):
    return JSONResponse(content={'status': 'ok', 'page_size': page_size})


@app.get('/items')
def list_items(request: Request, page_size: int = Depends(get_page_size)):
    limit = None
    raw_limit = request.query_params.get('limit')
    if raw_limit is not None:
        try:
            limit = int(raw_limit)
        except ValueError:
            limit = None

    if not limit:
        limit = page_size

    items = list(_ITEMS.values())[:limit]
    return JSONResponse(content={'items': items, 'count': len(items)})


@app.get('/items/{item_id}')
def get_item(item_id: int):
    item = _ITEMS.get(item_id)
    if item is None:
        return _json_error('item not found', 404)
    return JSONResponse(content=item)


@app.post('/items')
async def create_item(request: Request):
    data = None
    content_type = request.headers.get('content-type')
    if _is_json_content_type(content_type):
        body = await request.body()
        try:
            data = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            data = None

    if not data:
        return _json_error('body must be JSON', 400)
    if 'name' not in data:
        return _json_error('name is required', 400)
    if not isinstance(data['name'], str):
        return _json_error('name must be a string', 400)

    qty = data.get('qty', 0)
    new_id = max(_ITEMS) + 1
    return JSONResponse(
        content={'id': new_id, 'name': data['name'], 'qty': qty},
        status_code=201,
    )


@app.delete('/items/{item_id}')
def delete_item(item_id: int):
    if item_id not in _ITEMS:
        return _json_error('item not found', 404)
    return JSONResponse(content={'deleted': item_id})
"}

