{"code": "'''Optimistic concurrency with a version header. Synthetic case.

Exercises: a request header that drives control flow, PATCH semantics, 409 on a
version mismatch, 428 when the header is absent, and a response header echoing the
new version.
'''

import json

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)

_DOCS = {'d1': {'id': 'd1', 'title': 'spec', 'version': 3}}


class FlaskJSONResponse(JSONResponse):
    def render(self, content):
        return json.dumps(content, sort_keys=True, separators=(',', ':'), ensure_ascii=True, allow_nan=True).encode('utf-8') + chr(10).encode()


def _json_response(data, status_code=200, headers=None):
    return FlaskJSONResponse(content=data, status_code=status_code, headers=headers)


@app.get('/docs/{doc_id}')
async def get_doc(doc_id: str):
    doc = _DOCS.get(doc_id)
    if doc is None:
        return _json_response({'error': 'doc not found'}, status_code=404)
    etag = 'W/' + chr(34) + str(doc['version']) + chr(34)
    return _json_response(doc, status_code=200, headers={'ETag': etag})


@app.patch('/docs/{doc_id}')
async def patch_doc(doc_id: str, request: Request):
    doc = _DOCS.get(doc_id)
    if doc is None:
        return _json_response({'error': 'doc not found'}, status_code=404)

    if_match = request.headers.get('If-Match')
    if not if_match:
        return _json_response({'error': 'If-Match header is required', 'code': 'PRECONDITION_REQUIRED'}, status_code=428)
    expected = 'W/' + chr(34) + str(doc['version']) + chr(34)
    if if_match != expected:
        return _json_response({'error': 'version conflict', 'expected': doc['version']}, status_code=409)

    content_type = request.headers.get('content-type', '')
    media_type = content_type.split(';', 1)[0].strip().lower()
    is_json = media_type == 'application/json' or media_type.endswith('+json')

    data = {}
    if is_json:
        raw = await request.body()
        parsed = None
        if raw:
            try:
                parsed = json.loads(raw)
            except (json.JSONDecodeError, UnicodeDecodeError):
                parsed = None
        data = parsed or {}

    title = data.get('title')
    if not isinstance(title, str) or not title:
        return _json_response({'error': 'title must be a non-empty string'}, status_code=400)

    new_doc = {**doc, 'title': title, 'version': doc['version'] + 1}
    etag = 'W/' + chr(34) + str(new_doc['version']) + chr(34)
    return _json_response(new_doc, status_code=200, headers={'ETag': etag})
"}

{"code": "'''Trailing-slash and redirect behaviour migrated to FastAPI.'''

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response
from starlette.exceptions import HTTPException as StarletteHTTPException

app = FastAPI(redirect_slashes=False)

_NOT_FOUND_HTML = '''<!doctype html>
<html lang=en>
<title>404 Not Found</title>
<h1>Not Found</h1>
<p>The requested URL was not found on the server. If you entered the URL manually please check your spelling and try again.</p>'''

_METHOD_NOT_ALLOWED_HTML = '''<!doctype html>
<html lang=en>
<title>405 Method Not Allowed</title>
<h1>Method Not Allowed</h1>
<p>The method is not allowed for the requested URL.</p>'''


@app.exception_handler(StarletteHTTPException)
async def http_exception_handler(request: Request, exc: StarletteHTTPException):
    if exc.status_code == 404:
        return Response(_NOT_FOUND_HTML, status_code=404, media_type='text/html')
    if exc.status_code == 405:
        return Response(_METHOD_NOT_ALLOWED_HTML, status_code=405, media_type='text/html', headers=exc.headers)
    return JSONResponse(status_code=exc.status_code, content={'detail': exc.detail}, headers=exc.headers)


@app.middleware('http')
async def flask_slash_middleware(request: Request, call_next):
    path = request.url.path
    if path == '/reports':
        location = '/reports/'
        query_string = request.scope.get('query_string')
        if query_string:
            location += '?' + query_string.decode('latin-1')
        body = f'''<!doctype html>
<html lang=en>
<title>Redirecting...</title>
<h1>Redirecting...</h1>
<p>You should be redirected automatically to target URL: <a href='{location}'>{location}</a>.  If not click the link.
'''
        return Response(body, status_code=308, media_type='text/html', headers={'Location': location})
    if path == '/jobs/':
        return JSONResponse({'jobs': []})
    return await call_next(request)


@app.get('/reports/')
def list_reports():
    return {'reports': ['daily', 'weekly']}


@app.get('/status')
def status():
    return {'status': 'up'}


@app.get('/jobs')
def jobs():
    return {'jobs': []}


@app.get('/queue/{name}')
def queue(name: str):
    return {'queue': name, 'depth': 0}
