{"code": "import json

from fastapi import FastAPI, Request
from fastapi.responses import Response


app = FastAPI()

_USERS = {"u1": {"id": "u1", "name": "ana", "tier": "pro"}}
_BALANCES = {"u1": 50}
DEPRECATION = "version=1; sunset=2027-01-01"


def _v1_headers(response):
    response.headers["X-API-Deprecation"] = DEPRECATION
    return response


def _json_response(data, status_code=200):
    body = json.dumps(data, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
    return Response(content=body.encode("utf-8"), media_type="application/json", status_code=status_code)


async def _get_json(request):
    raw = await request.body()
    if not raw:
        return None
    try:
        return json.loads(raw)
    except ValueError:
        return None


@app.get("/v1/users/{user_id}")
async def v1_get_user(user_id: str):
    user = _USERS.get(user_id, {})
    return _v1_headers(_json_response(user, 200))


@app.get("/v2/users/{user_id}")
async def v2_get_user(user_id: str):
    user = _USERS.get(user_id)
    if user is None:
        return _json_response({"message": "user not found"}, 404)
    return _json_response({"data": user})


@app.post("/v1/charge")
async def v1_charge(request: Request):
    body = await _get_json(request) or {}
    user_id = body.get("user_id")
    amount = body.get("amount")

    if not user_id:
        return _v1_headers(_json_response({"error": "user_id required", "ok": False}, 200))
    if not isinstance(amount, int):
        return _v1_headers(_json_response({"error": "amount must be an integer", "ok": False}, 200))
    balance = _BALANCES.get(user_id)
    if balance is None:
        return _v1_headers(_json_response({"error": "unknown user", "ok": False}, 200))
    if amount > balance:
        return _v1_headers(_json_response({"error": "insufficient funds", "ok": False}, 200))
    return _v1_headers(_json_response({"ok": True, "remaining": balance - amount}, 200))


@app.post("/v2/charge")
async def v2_charge(request: Request):
    body = await _get_json(request) or {}
    if "user_id" not in body:
        return _json_response({"field": "user_id", "message": "user_id required"}, 422)
    amount = body.get("amount")
    if not isinstance(amount, int):
        return _json_response({"field": "amount", "message": "amount must be an integer"}, 422)
    balance = _BALANCES.get(body["user_id"])
    if balance is None:
        return _json_response({"message": "unknown user"}, 404)
    if amount > balance:
        return _json_response({"balance": balance, "message": "insufficient funds"}, 402)
    return _json_response({"remaining": balance - amount}, 200)


@app.get("/v1/ping")
async def v1_ping():
    return _v1_headers(Response(content=b"pong", media_type="text/html", status_code=200))


@app.get("/v2/ping")
async def v2_ping():
    return _json_response("pong")


@app.post("/v2/batch")
async def v2_batch(request: Request):
    body = await _get_json(request)
    if not isinstance(body, list):
        return _json_response({"message": "body must be a JSON array"}, 422)

    outcomes = []
    for index, entry in enumerate(body):
        if not isinstance(entry, dict) or "user_id" not in entry:
            outcomes.append({"index": index, "ok": False, "error": "malformed entry"})
        elif entry["user_id"] not in _USERS:
            outcomes.append({"index": index, "ok": False, "error": "unknown user"})
        else:
            outcomes.append({"index": index, "ok": True})

    failures = sum(1 for o in outcomes if not o["ok"])
    status = 200 if failures == 0 else 207
    return _json_response({"outcomes": outcomes, "failures": failures}, status)


@app.get("/v1/config")
async def v1_config():
    return _v1_headers(_json_response({
        "deprecated": True,
        "deprecation": DEPRECATION,
        "isDeprecated": True,
        "tiers": ["free", "pro"],
    }, 200))
"}

{"code": "import json

from fastapi import FastAPI, Request
from fastapi.responses import Response

app = FastAPI(redirect_slashes=False)

TRANSITIONS = {
    'draft': ['submitted', 'cancelled'],
    'submitted': ['approved', 'rejected', 'cancelled'],
    'approved': ['fulfilled'],
    'rejected': [],
    'cancelled': [],
    'fulfilled': [],
}
TERMINAL = {'rejected', 'cancelled', 'fulfilled'}

_ORDERS = {
    'o1': {'id': 'o1', 'state': 'draft', 'total': 30, 'lines': 2},
    'o2': {'id': 'o2', 'state': 'approved', 'total': 90, 'lines': 5},
}
_IDEMPOTENCY = {}
_NEXT = [3]


def _present(order):
    return {**order, 'terminal': order['state'] in TERMINAL}


def _json_response(data, status_code=200, headers=None):
    body = json.dumps(data, sort_keys=True, separators=(',', ':'))
    response_headers = {'content-type': 'application/json'}
    if headers:
        response_headers.update(headers)
    return Response(content=body.encode('utf-8'), status_code=status_code, headers=response_headers)


def _is_json(content_type):
    if not content_type:
        return False
    mimetype = content_type.split(';', 1)[0].strip().lower()
    return mimetype == 'application/json' or (
        mimetype.startswith('application/') and mimetype.endswith('+json')
    )


async def _read_json(request):
    if not _is_json(request.headers.get('content-type', '')):
        return {}
    try:
        return await request.json()
    except Exception:
        return {}


@app.get('/orders/{order_id}')
async def get_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return _json_response({'error': 'order not found', 'id': order_id}, 404)
    return _json_response(_present(order))


@app.post('/orders')
async def create_order(request: Request):
    body = await _read_json(request) or {}
    total = body.get('total')
    if not isinstance(total, int) or total <= 0:
        return _json_response({'error': 'total must be a positive integer'}, 400)

    key = request.headers.get('Idempotency-Key')
    if key:
        seen = _IDEMPOTENCY.get(key)
        if seen is not None:
            if seen['total'] != total:
                return _json_response({
                    'error': 'idempotency key reused with a different body',
                    'code': 'IDEMPOTENCY_MISMATCH',
                }, 422)
            return _json_response(_present(_ORDERS[seen['id']]), 200)

    order_id = f'o{_NEXT[0]}'
    _NEXT[0] += 1
    order = {
        'id': order_id,
        'state': 'draft',
        'total': total,
        'lines': body.get('lines', 1),
    }
    _ORDERS[order_id] = order
    if key:
        _IDEMPOTENCY[key] = {'id': order_id, 'total': total}

    return _json_response(_present(order), 201, headers={'Location': f'/orders/{order_id}'})


@app.post('/orders/{order_id}/transition')
async def transition(order_id: str, request: Request):
    order = _ORDERS.get(order_id)
    if order is None:
        return _json_response({'error': 'order not found', 'id': order_id}, 404)

    body = await _read_json(request) or {}
    target = body.get('to')
    if not target:
        return _json_response({'error': 'to is required'}, 400)
    if target not in TRANSITIONS:
        return _json_response({'error': 'unknown state', 'state': target}, 400)

    allowed = TRANSITIONS[order['state']]
    if target not in allowed:
        return _json_response({
            'error': 'illegal transition',
            'from': order['state'],
            'to': target,
            'allowed': allowed,
        }, 409)

    order['state'] = target
    return _json_response(_present(order))


@app.delete('/orders/{order_id}')
async def delete_order(order_id: str):
    order = _ORDERS.get(order_id)
    if order is None:
        return _json_response({'error': 'order not found', 'id': order_id}, 404)
    if order['state'] != 'draft':
        return _json_response({
            'error': 'only draft orders can be deleted',
            'state': order['state'],
            'code': 'NOT_DELETABLE',
        }, 409)
    return Response(status_code=204)


@app.get('/orders')
async def list_orders(request: Request):
    state = request.query_params.get('state')
    rows = list(_ORDERS.values())
    if state:
        if state not in TRANSITIONS:
            return _json_response({'error': 'unknown state', 'state': state}, 400)
        rows = [o for o in rows if o['state'] == state]
    return _json_response({'orders': [_present(o) for o in rows], 'count': len(rows)})
"}
